INSERT INTO public.content_items(id,kind,data,published) VALUES ('malala','feed','{"id":"malala","type":"stories","icon":"sprout","color":"rose","source":"Malala Fund","tags":["courage","fear","hope"],"title":{"en":"A voice that fear could not silence","pt":"Uma voz que o medo não calou","es":"Una voz que el miedo no pudo callar","ru":"Голос, который не заглушил страх"},"summary":{"en":"After surviving an attack in 2012, Malala continued her work for girls’ education. Her story is about courage, recovery, and the people who help us begin again.","pt":"Após sobreviver a um atentado em 2012, Malala continuou sua luta pela educação das meninas. Uma história de coragem, recuperação e das pessoas que nos ajudam a recomeçar.","es":"Tras sobrevivir a un atentado en 2012, Malala continuó defendiendo la educación de las niñas. Una historia de valor, recuperación y de quienes nos ayudan a empezar de nuevo.","ru":"После нападения в 2012 году Малала продолжила защищать право девочек на образование. Это история смелости, восстановления и людей, которые помогают начать снова."},"body":{"en":"Before the headlines\n\nMalala Yousafzai grew up in Mingora, Pakistan, where her father ran a school. When the Taliban imposed restrictions in the Swat Valley, girls’ access to education became a central concern in her life. She spoke publicly and wrote about her experiences for BBC Urdu while still a child.\n\nIn October 2012, a gunman attacked her on her way home from school. She survived and received treatment in Birmingham. The attack was not the end of her public work, but neither should survival be reduced to an effortless triumph: recovery, family and support belong in the story too.\n\nWork beyond one person\n\nIn 2013, Malala and her father established Malala Fund. In 2014 she received the Nobel Peace Prize. The organisation’s work connects her story to a wider effort for girls’ education, rather than treating courage as something only an exceptional individual possesses.\n\nWatch and explore\n\nThe British Council resource below contains the trailer for “He Named Me Malala,” a transcript and learning exercises. It is a trailer, not the complete documentary. Malala Fund’s own timeline provides the fuller biographical account.\n\nFor reflection\n\nWho helped make a difficult step possible in your life? Consider one practical way to support another person’s learning—listening, sharing a resource or helping them find an opportunity. This invitation is our reflection, not advice attributed to Malala.","pt":"Antes das manchetes\n\nMalala Yousafzai cresceu em Mingora, no Paquistão, onde seu pai dirigia uma escola. Quando o Talibã impôs restrições no vale do Swat, o acesso das meninas à educação tornou-se uma preocupação central. Ainda criança, ela falou publicamente e escreveu sobre suas experiências para a BBC Urdu.\n\nEm outubro de 2012, um homem armado a atacou na volta da escola. Ela sobreviveu e recebeu tratamento em Birmingham. O ataque não encerrou sua atuação, mas sobreviver não deve ser apresentado como uma vitória sem esforço: recuperação, família e apoio também fazem parte da história.\n\nUm trabalho que vai além de uma pessoa\n\nEm 2013, Malala e seu pai criaram o Malala Fund. Em 2014, ela recebeu o Nobel da Paz. O trabalho da organização liga sua história a um esforço mais amplo pela educação das meninas, sem tratar a coragem como algo reservado a uma pessoa excepcional.\n\nAssista e conheça mais\n\nO material do British Council abaixo inclui o trailer de “He Named Me Malala”, transcrição e exercícios. É um trailer, não o documentário completo. A linha do tempo do Malala Fund traz o relato biográfico mais amplo.\n\nPara refletir\n\nQuem ajudou você a dar um passo difícil? Pense em uma forma concreta de apoiar a aprendizagem de alguém: escutar, compartilhar um recurso ou ajudar a encontrar uma oportunidade. Esta é uma reflexão nossa, não um conselho atribuído a Malala.","es":"Antes de los titulares\n\nMalala Yousafzai creció en Mingora, Pakistán, donde su padre dirigía una escuela. Cuando los talibanes impusieron restricciones en el valle de Swat, el acceso de las niñas a la educación se convirtió en una preocupación central. Siendo niña, habló públicamente y escribió sobre su experiencia para BBC Urdu.\n\nEn octubre de 2012, un hombre armado la atacó cuando regresaba de la escuela. Sobrevivió y recibió tratamiento en Birmingham. El ataque no acabó con su trabajo público, pero sobrevivir no debe presentarse como un triunfo sin esfuerzo: recuperación, familia y apoyo también forman parte de la historia.\n\nMás allá de una persona\n\nEn 2013, Malala y su padre crearon Malala Fund. En 2014 recibió el Nobel de la Paz. La organización conecta su historia con un esfuerzo colectivo por la educación de las niñas, en lugar de reservar la valentía a una persona excepcional.\n\nVer y explorar\n\nEl recurso del British Council incluye el tráiler de “He Named Me Malala”, una transcripción y ejercicios. Es un tráiler, no el documental completo. La cronología de Malala Fund ofrece el relato biográfico más amplio.\n\nPara reflexionar\n\n¿Quién te ayudó a dar un paso difícil? Piensa en una forma concreta de apoyar el aprendizaje de alguien: escuchar, compartir un recurso o ayudar a encontrar una oportunidad. Esta reflexión es nuestra, no un consejo atribuido a Malala.","ru":"До газетных заголовков\n\nМалала Юсуфзай выросла в Мингоре, Пакистан, где её отец руководил школой. После ограничений, введённых талибами в долине Сват, образование девочек стало для неё особенно важным вопросом. Ещё ребёнком она выступала публично и писала о своём опыте для BBC Urdu.\n\nВ октябре 2012 года вооружённый человек напал на неё по дороге из школы. Она выжила и проходила лечение в Бирмингеме. Нападение не прекратило её общественную деятельность, но выживание нельзя представлять лёгкой победой: восстановление, семья и поддержка тоже входят в эту историю.\n\nРабота шире одной судьбы\n\nВ 2013 году Малала и её отец создали Malala Fund. В 2014 году она получила Нобелевскую премию мира. Организация связывает её историю с общими усилиями ради образования девочек, а не представляет мужество исключительным качеством одного человека.\n\nПосмотреть и узнать больше\n\nМатериал British Council содержит трейлер «He Named Me Malala», расшифровку и упражнения. Это трейлер, не полный документальный фильм. Биографическая хронология Malala Fund рассказывает историю подробнее.\n\nДля размышления\n\nКто помог вам сделать трудный шаг? Подумайте о конкретной поддержке чужого обучения: выслушать, поделиться материалом или помочь найти возможность. Это наше приглашение к размышлению, а не совет, приписанный Малале."},"resources":[["read","Malala Fund","https://malala.org/malalas-story"],["watch","He Named Me Malala · trailer & exercises","https://learnenglishteens.britishcouncil.org/study-break/video-zone/he-named-me-malala"]],"kind":"feed"}'::jsonb,true) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.content_items(id,kind,data,published) VALUES ('psalm-23','feed','{"id":"psalm-23","type":"psalms","icon":"leaf","color":"sage","source":"Scripture · Psalm 23 / 22","tags":["fear","comfort","trust"],"title":{"en":"You are not alone in the valley","pt":"Você não está só no vale","es":"No estás solo en el valle","ru":"Вы не одни в долине"},"summary":{"en":"Psalm 23 uses the images of a shepherd and a welcoming host to speak of care in uncertainty. Read its context, or listen to a contemporary song inspired by its words.","pt":"O Salmo 23 usa as imagens do pastor e do anfitrião para falar de cuidado na incerteza. Conheça o contexto ou ouça uma canção contemporânea inspirada nele.","es":"El Salmo 23 usa las imágenes de un pastor y un anfitrión para hablar de cuidado en la incertidumbre. Lee el contexto o escucha una canción inspirada en sus palabras.","ru":"Псалом 23 (22) говорит о заботе через образы пастыря и гостеприимного хозяина. Узнайте контекст или послушайте современную песню по мотивам псалма."},"body":{"en":"The USCCB’s Catholic study notes connect these images with Israel’s exodus traditions. This is literary and theological context; the notes do not establish a precise composition date. Numbered Psalm 22 in many Septuagint-based editions. The linked song is an adaptation, not a Bible translation.","pt":"As notas católicas da USCCB relacionam essas imagens às tradições do êxodo de Israel. É um contexto literário e teológico, sem data exata de composição. Muitas edições baseadas na Septuaginta o numeram como Salmo 22. A canção é uma adaptação, não uma tradução bíblica.","es":"Las notas católicas de la USCCB relacionan estas imágenes con el éxodo de Israel. Es contexto literario y teológico, sin fecha exacta de composición. En muchas ediciones de la Septuaginta es el Salmo 22. La canción es una adaptación, no una traducción bíblica.","ru":"Католические примечания USCCB связывают эти образы с исходом Израиля. Это литературный и богословский контекст, без точной даты создания. В изданиях на основе Септуагинты это Псалом 22. Песня — переложение, а не перевод Библии."},"resources":[["study","USCCB · Catholic study notes","https://bible.usccb.org/bible/psalms/23"],["listen","Shane & Shane · Psalm 23","https://www.youtube.com/watch?v=OoojA0cLPWY"]],"kind":"feed"}'::jsonb,true) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.content_items(id,kind,data,published) VALUES ('harpa','feed','{"id":"harpa","type":"music","icon":"music","color":"sand","source":"Harpa Cristã · CPAD","tags":["belonging","hope","worship"],"title":{"en":"Songs that carry a community","pt":"Hinos que carregam uma comunidade","es":"Himnos que sostienen a una comunidad","ru":"Гимны, объединяющие людей"},"summary":{"en":"Harpa Cristã began in Recife in 1922 and became the Brazilian Assemblies of God’s hymnbook. Explore the collection’s history and official performances, including “Vivifica,” hymn 530.","pt":"A Harpa Cristã nasceu no Recife em 1922 e tornou-se o hinário das Assembleias de Deus no Brasil. Conheça sua história e apresentações oficiais, incluindo “Vivifica”, hino 530.","es":"Harpa Cristã nació en Recife en 1922 como himnario de las Asambleas de Dios en Brasil. Descubre su historia e interpretaciones oficiales, como “Vivifica”, himno 530.","ru":"Harpa Cristã появилась в Ресифи в 1922 году и стала сборником гимнов бразильских Ассамблей Бога. Узнайте историю и послушайте официальные исполнения, включая гимн 530 «Vivifica»."},"body":{"en":"A hymnbook for a growing church\n\nHarpa Cristã’s first edition appeared in Recife in 1922. It served the Assemblies of God in Brazil across ordinary worship and major moments of life: communion, baptism, marriage and funerals. The initial print run was 1,000 copies, distributed by missionary Samuel Nyström.\n\nThe collection grew quickly: the 1923 edition contained 300 hymns, and by 1932 there were 400. Nyström translated Scandinavian hymn texts; Paulo Leivas Macalão helped adapt words to their melodies. This was also work across languages, so a congregation could sing together rather than merely read a translation.\n\nLater revisions changed the collection again. The expanded 1999 edition contained 640 hymns. CPAD’s history records a later revision to 636 after four national patriotic songs were removed. Different editions therefore need not have identical contents.\n\nListen with that history in mind\n\nCPAD’s video collection includes “Vivifica” (530), “Não Murmures: Canta” (302), “O Bom Consolador” (100), and a historical presentation. These are publisher-hosted performances and background resources, not recordings made by Grace & Gather.\n\nA listening invitation\n\nChoose one performance below. Notice whether its language expresses a personal request, shared hope or encouragement to others. You do not have to sing along. After listening, ask: what would I like to say to God in my own words?","pt":"Um hinário para uma igreja em crescimento\n\nA primeira edição da Harpa Cristã apareceu no Recife em 1922. Ela acompanhava as Assembleias de Deus no Brasil tanto nos cultos quanto em momentos importantes da vida: Santa Ceia, batismo, casamento e funerais. A tiragem inicial foi de mil exemplares, distribuídos pelo missionário Samuel Nyström.\n\nA coletânea cresceu rapidamente: a edição de 1923 tinha 300 hinos e, em 1932, eram 400. Nyström traduziu letras escandinavas; Paulo Leivas Macalão ajudou a adaptar as palavras às melodias. Era também um trabalho entre línguas, para que a comunidade pudesse cantar unida, e não apenas ler uma tradução.\n\nRevisões posteriores voltaram a mudar a coletânea. A edição ampliada de 1999 reuniu 640 hinos. A história da CPAD registra uma revisão posterior para 636, com a retirada de quatro hinos nacionais patrióticos. Por isso, edições diferentes podem ter conteúdos diferentes.\n\nOuça com essa história em mente\n\nA coleção de vídeos da CPAD inclui “Vivifica” (530), “Não Murmures: Canta” (302), “O Bom Consolador” (100) e uma apresentação histórica. São interpretações e materiais da editora, não gravações produzidas pelo Grace & Gather.\n\nUm convite para escutar\n\nEscolha uma apresentação abaixo. Observe se as palavras expressam um pedido pessoal, esperança compartilhada ou encorajamento. Você não precisa cantar junto. Depois, pergunte: o que eu gostaria de dizer a Deus com minhas próprias palavras?","es":"Un himnario para una iglesia en crecimiento\n\nLa primera edición de Harpa Cristã apareció en Recife en 1922. Acompañaba a las Asambleas de Dios de Brasil en el culto y en momentos importantes: comunión, bautismos, bodas y funerales. La tirada inicial fue de mil ejemplares, distribuidos por el misionero Samuel Nyström.\n\nLa colección creció pronto: la edición de 1923 contenía 300 himnos y en 1932 eran 400. Nyström tradujo letras escandinavas; Paulo Leivas Macalão ayudó a adaptar las palabras a las melodías. También era un trabajo entre lenguas para que la congregación pudiera cantar unida, no solamente leer una traducción.\n\nLa edición ampliada de 1999 reunió 640 himnos. La historia de CPAD registra una revisión posterior a 636 tras retirar cuatro canciones patrióticas nacionales. Por eso, distintas ediciones pueden tener contenidos diferentes.\n\nEscuchar con esa historia presente\n\nLa colección de vídeos de CPAD incluye “Vivifica” (530), “Não Murmures: Canta” (302), “O Bom Consolador” (100) y una presentación histórica. Son interpretaciones y recursos de la editorial, no grabaciones de Grace & Gather.\n\nUna invitación\n\nElige una interpretación abajo. Observa si expresa una petición personal, esperanza compartida o ánimo para otros. No necesitas cantar. Después, pregúntate: ¿qué quisiera decirle a Dios con mis propias palabras?","ru":"Сборник гимнов для растущей церкви\n\nПервое издание Harpa Cristã вышло в Ресифи в 1922 году. Оно сопровождало бразильские Ассамблеи Бога на богослужениях, причастии, крещениях, свадьбах и похоронах. Первый тираж составил тысячу экземпляров; их распространял миссионер Самуэль Нюстрём.\n\nСборник быстро рос: издание 1923 года включало 300 гимнов, а к 1932 году — 400. Нюстрём переводил скандинавские тексты; Паулу Лейвас Макалан помогал согласовать слова с мелодиями. Работа между языками позволяла общине петь вместе, а не только читать перевод.\n\nРасширенное издание 1999 года содержало 640 гимнов. В истории CPAD описано последующее сокращение до 636 после удаления четырёх национальных патриотических песен. Поэтому содержание разных изданий может отличаться.\n\nПослушайте, помня эту историю\n\nВидеоколлекция CPAD включает «Vivifica» (530), «Não Murmures: Canta» (302), «O Bom Consolador» (100) и исторический рассказ. Это исполнения и материалы издателя, а не записи Grace & Gather.\n\nПриглашение к слушанию\n\nВыберите исполнение ниже. Обратите внимание: это личная просьба, общая надежда или поддержка другим? Подпевать необязательно. После прослушивания спросите себя: что я хочу сказать Богу своими словами?"},"resources":[["read","Harpa Cristã · história","https://www.harpacrista.com.br/historia/"],["listen","CPAD · performances","https://www.harpacrista.com.br/video/"]],"kind":"feed"}'::jsonb,true) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.content_items(id,kind,data,published) VALUES ('ruth','feed','{"id":"ruth","type":"bible","icon":"play","color":"lavender","source":"BibleProject","tags":["grief","friendship","hope"],"title":{"en":"Ruth: companionship after loss","pt":"Rute: companhia depois da perda","es":"Rut: compañía después de la pérdida","ru":"Руфь: близость после утраты"},"summary":{"en":"Loss brings Naomi and Ruth into a difficult new chapter. This animated overview follows their loyalty, everyday courage, and the people who make a new beginning possible.","pt":"A perda leva Noemi e Rute a um capítulo difícil. Esta animação acompanha sua lealdade, coragem cotidiana e as pessoas que tornam possível um recomeço.","es":"La pérdida lleva a Noemí y Rut a una etapa difícil. Esta animación sigue su lealtad, valor cotidiano y a quienes hacen posible un nuevo comienzo.","ru":"Утрата открывает трудную главу в жизни Ноемини и Руфи. Анимация рассказывает о верности, повседневной смелости и людях, помогающих начать заново."},"body":{"en":"A story that begins with loss\n\nRuth opens during the time of the judges. Famine takes Naomi’s family from Bethlehem to Moab. Her husband and both sons die there, leaving Naomi and her daughters-in-law Ruth and Orpah. Naomi decides to return home. Ruth chooses to accompany her, crossing the boundary between her own people and Naomi’s community.\n\nCare becomes practical\n\nIn chapter 2, Ruth gathers leftover grain in the fields of Boaz. Food, safety and access to work matter here: kindness is not only a comforting speech. Boaz makes room for Ruth, a foreign widow, and Naomi begins to imagine a future again.\n\nIn chapters 3–4, questions of family responsibility and redemption shape Ruth and Boaz’s marriage. The ending connects their son Obed to the family line of David. The story moves from a vulnerable household toward a future larger than its characters can see.\n\nRead beyond the romance\n\nRead the four chapters with three questions: who is vulnerable, who has power to help, and what does that person actually do? Notice Naomi’s grief alongside Ruth’s loyalty. The ending does not require readers to pretend the opening losses never happened.\n\nThe animated overview below is about seven minutes long. BibleProject’s accompanying guide explores the chapters and the theme of loyal love. These resources offer one interpretive approach; return to the biblical text in your chosen edition as you study.","pt":"Uma história que começa com perdas\n\nRute se passa no tempo dos juízes. A fome leva a família de Noemi de Belém para Moabe. Ali morrem seu marido e seus dois filhos, deixando Noemi e suas noras Rute e Orfa. Noemi decide voltar para casa. Rute escolhe acompanhá-la, atravessando a distância entre seu próprio povo e a comunidade de Noemi.\n\nO cuidado se torna concreto\n\nNo capítulo 2, Rute recolhe as espigas que restam nos campos de Boaz. Comida, segurança e acesso ao trabalho importam: bondade não é apenas um discurso acolhedor. Boaz abre espaço para Rute, uma viúva estrangeira, e Noemi começa a imaginar novamente um futuro.\n\nNos capítulos 3–4, responsabilidade familiar e resgate fazem parte do casamento de Rute e Boaz. O final liga seu filho Obede à linhagem de Davi. A história sai da vulnerabilidade de uma família para um futuro maior do que seus personagens conseguem enxergar.\n\nLeia além do romance\n\nLeia os quatro capítulos perguntando: quem está vulnerável, quem pode ajudar e o que essa pessoa faz? Observe o luto de Noemi junto da lealdade de Rute. O final não exige fingir que as perdas iniciais não aconteceram.\n\nA animação abaixo dura cerca de sete minutos. O guia do BibleProject aprofunda os capítulos e o amor leal. É uma abordagem interpretativa; volte ao texto bíblico na edição que você escolheu.","es":"Una historia que comienza con pérdidas\n\nRut transcurre en tiempos de los jueces. El hambre lleva a la familia de Noemí de Belén a Moab. Allí mueren su esposo y sus dos hijos, quedando Noemí y sus nueras Rut y Orfa. Noemí decide volver a casa. Rut elige acompañarla, cruzando la distancia entre su propio pueblo y la comunidad de Noemí.\n\nEl cuidado se vuelve concreto\n\nEn el capítulo 2, Rut recoge el grano sobrante en los campos de Booz. Alimento, seguridad y acceso al trabajo importan: la bondad no es solo un discurso consolador. Booz hace espacio para Rut, una viuda extranjera, y Noemí vuelve a imaginar un futuro.\n\nEn los capítulos 3–4, la responsabilidad familiar y la redención enmarcan el matrimonio de Rut y Booz. El final conecta a su hijo Obed con el linaje de David. La historia pasa de una familia vulnerable a un futuro más amplio del que sus personajes pueden ver.\n\nLeer más allá del romance\n\nLee los cuatro capítulos preguntando: ¿quién es vulnerable, quién puede ayudar y qué hace esa persona? Observa el duelo de Noemí junto a la lealtad de Rut. El final no exige fingir que las pérdidas iniciales nunca ocurrieron.\n\nLa animación dura unos siete minutos. La guía de BibleProject explora los capítulos y el amor leal. Es una perspectiva interpretativa; vuelve al texto bíblico en tu edición elegida.","ru":"История, начинающаяся с утраты\n\nКнига Руфи начинается во времена судей. Голод приводит семью Ноемини из Вифлеема в Моав. Там умирают её муж и оба сына; остаются Ноеминь и её невестки Руфь и Орфа. Ноеминь решает вернуться домой. Руфь идёт с ней, переходя границу между своим народом и общиной Ноемини.\n\nЗабота становится конкретной\n\nВо второй главе Руфь собирает оставшиеся колосья на поле Вооза. Здесь важны еда, безопасность и возможность трудиться: доброта не ограничивается утешительными словами. Вооз помогает чужеземной вдове, и Ноеминь снова начинает представлять будущее.\n\nВ главах 3–4 семейная ответственность и выкуп определяют обстоятельства брака Руфи и Вооза. Финал связывает их сына Овида с родословием Давида. Рассказ выходит за пределы уязвимой семьи к будущему, которого герои пока не видят.\n\nЧитайте не только как историю любви\n\nПрочитайте четыре главы с вопросами: кто уязвим, кто может помочь и что этот человек делает? Заметьте горе Ноемини рядом с верностью Руфи. Финал не требует делать вид, будто прежних потерь не было.\n\nАнимационный обзор ниже длится около семи минут. Материал BibleProject раскрывает главы и тему верной любви. Это один подход к толкованию; возвращайтесь к библейскому тексту в выбранном издании."},"resources":[["watch","BibleProject · 7 min","https://bibleproject.com/videos/ruth/"],["study","Book of Ruth guide","https://bibleproject.com/guides/book-of-ruth/"]],"kind":"feed"}'::jsonb,true) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.content_items(id,kind,data,published) VALUES ('joni','feed','{"id":"joni","type":"stories","icon":"sun","color":"sand","source":"Joni and Friends","tags":["testimony","purpose","faith"],"title":{"en":"Finding purpose through a changed life","pt":"Encontrar propósito numa vida transformada","es":"Encontrar propósito en una vida distinta","ru":"Смысл в изменившейся жизни"},"summary":{"en":"A diving accident in 1967 left Joni Eareckson Tada with quadriplegia. In her own account, faith and community became part of living with hardship and supporting others with disabilities.","pt":"Um acidente de mergulho em 1967 deixou Joni Eareckson Tada tetraplégica. Em seu relato, a fé e a comunidade a acompanham na vida com dificuldades e no apoio a pessoas com deficiência.","es":"Un accidente de buceo en 1967 dejó a Joni Eareckson Tada con tetraplejia. En su relato, la fe y la comunidad la acompañan en las dificultades y en su apoyo a otras personas con discapacidad.","ru":"После несчастного случая при нырянии в 1967 году Джони Эриксон Тада живёт с тетраплегией. По её рассказу, вера и община помогают переносить трудности и поддерживать людей с инвалидностью."},"body":{"en":"Her organization shares her story in writing and video, alongside reflections on faith and disability. This is one person’s Christian testimony, not a cure story or evidence that faith removes depression or disability.","pt":"Sua organização compartilha sua história em texto e vídeo, junto a reflexões sobre fé e deficiência. É um testemunho cristão pessoal, não um relato de cura ou evidência de que a fé elimina depressão ou deficiência.","es":"Su organización comparte su historia y reflexiones en texto y vídeo. Es un testimonio cristiano personal, no una historia de curación ni una prueba de que la fe elimine la depresión o la discapacidad.","ru":"Организация Джони публикует её рассказ и размышления в текстах и видео. Это личное христианское свидетельство, а не история исцеления или доказательство того, что вера устраняет депрессию либо инвалидность."},"resources":[["watch","Joni’s story","https://joniandfriends.org/about/"],["read","Joni’s Corner","https://joniandfriends.org/jonis-corner/"]],"kind":"feed"}'::jsonb,true) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.content_items(id,kind,data,published) VALUES ('amazing-grace','feed','{"id":"amazing-grace","type":"music","icon":"music","color":"rose","source":"Cowper & Newton Museum","tags":["grace","renewal","hope"],"title":{"en":"Amazing Grace: a hymn with a history","pt":"Amazing Grace: um hino com história","es":"Amazing Grace: un himno con historia","ru":"Amazing Grace: история гимна"},"summary":{"en":"John Newton’s hymn looks back on the past and toward hope. Probably written before his New Year’s Day service in 1773, it drew on 1 Chronicles 17:16–17 and appeared in Olney Hymns in 1779.","pt":"O hino de John Newton olha para o passado e para a esperança. Provavelmente escrito antes do culto de Ano Novo de 1773, baseia-se em 1 Crônicas 17:16–17 e saiu em Olney Hymns em 1779.","es":"El himno de John Newton mira al pasado y a la esperanza. Probablemente escrito antes de Año Nuevo de 1773, se basa en 1 Crónicas 17:16–17 y se publicó en Olney Hymns en 1779.","ru":"Гимн Джона Ньютона обращается к прошлому и надежде. Вероятно, он написан перед новогодней службой 1773 года по мотивам 1 Паралипоменон 17:16–17 и опубликован в Olney Hymns в 1779 году."},"body":{"en":"A hymn in a particular place and time\n\nJohn Newton wrote the words while serving as a minister in Olney, England. The Cowper & Newton Museum connects the hymn with his New Year’s Day service in 1773 and a sermon on 1 Chronicles 17:16–17. It appeared in the 1779 collection “Olney Hymns” under the title “Faith’s Review and Expectation.”\n\nThat setting matters. This was a congregation looking backward at the life already lived and forward to an uncertain year. The words of gratitude and dependence were not originally a modern performance created for a concert audience.\n\nA difficult history must remain visible\n\nNewton had participated in the slave trade. His later religious life did not erase that harm, and his public contribution to the abolition campaign came much later. In 1788 he published “Thoughts upon the African Slave Trade.” A meaningful account of grace should not compress this history into an instant, uncomplicated transformation.\n\nExplore the evidence\n\nThe museum resource below brings together the hymn, historical context and archival material. Read it before assuming that every popular story about the song’s origin is established fact. The separate song-library link is a place to explore performances, not a historical source.\n\nFor reflection\n\nWhat is the difference between feeling forgiven and taking responsibility? Sit with that question without rushing to a neat answer. This reflection is an invitation from Grace & Gather, not a quotation from Newton.","pt":"Um hino em um lugar e tempo concretos\n\nJohn Newton escreveu a letra quando era pastor em Olney, na Inglaterra. O Cowper & Newton Museum relaciona o hino ao culto de Ano-Novo de 1773 e a um sermão sobre 1 Crônicas 17:16–17. Ele apareceu na coletânea “Olney Hymns”, de 1779, com o título “Faith’s Review and Expectation”.\n\nEsse contexto importa. Era uma comunidade olhando para a vida já vivida e para um ano incerto. As palavras de gratidão e dependência não nasceram como uma apresentação moderna para uma plateia de concertos.\n\nUma história difícil precisa continuar visível\n\nNewton participou do tráfico de pessoas escravizadas. Sua vida religiosa posterior não apagou esse dano, e sua contribuição pública à campanha abolicionista veio bem depois. Em 1788, publicou “Thoughts upon the African Slave Trade”. Uma história significativa sobre a graça não deve reduzir tudo a uma transformação instantânea e sem conflitos.\n\nConheça as evidências\n\nO recurso do museu reúne o hino, contexto histórico e materiais de arquivo. Leia antes de considerar comprovada toda história popular sobre a origem da canção. O link separado para a biblioteca musical permite explorar interpretações; não é uma fonte histórica.\n\nPara refletir\n\nQual é a diferença entre sentir-se perdoado e assumir responsabilidade? Permaneça com essa pergunta sem correr para uma resposta simples. Esta reflexão é do Grace & Gather, não uma citação de Newton.","es":"Un himno en un lugar y tiempo concretos\n\nJohn Newton escribió la letra mientras era pastor en Olney, Inglaterra. El Cowper & Newton Museum relaciona el himno con el culto de Año Nuevo de 1773 y un sermón sobre 1 Crónicas 17:16–17. Apareció en “Olney Hymns”, de 1779, con el título “Faith’s Review and Expectation”.\n\nEse contexto importa: una congregación miraba la vida ya vivida y un año incierto. Las palabras de gratitud y dependencia no nacieron como una actuación moderna para un concierto.\n\nUna historia difícil debe permanecer visible\n\nNewton participó en la trata de personas esclavizadas. Su vida religiosa posterior no borró ese daño, y su contribución pública a la campaña abolicionista llegó mucho después. En 1788 publicó “Thoughts upon the African Slave Trade”. Un relato significativo sobre la gracia no debe reducirlo a una transformación instantánea y sin conflictos.\n\nExplora las evidencias\n\nEl recurso del museo reúne el himno, contexto histórico y archivos. Léelo antes de considerar demostrada cada historia popular sobre el origen de la canción. El enlace separado a la biblioteca musical permite explorar interpretaciones; no es una fuente histórica.\n\nPara reflexionar\n\n¿Qué diferencia hay entre sentirse perdonado y asumir responsabilidad? Quédate con esa pregunta sin buscar enseguida una respuesta sencilla. Esta reflexión es de Grace & Gather, no una cita de Newton.","ru":"Гимн в конкретном времени и месте\n\nДжон Ньютон написал слова, служа пастором в Олни, Англия. Музей Каупера и Ньютона связывает гимн с новогодним богослужением 1773 года и проповедью по 1 Паралипоменон 17:16–17. В сборнике «Olney Hymns» 1779 года он появился под названием «Faith’s Review and Expectation».\n\nКонтекст важен: община оглядывалась на прожитую жизнь и смотрела в неизвестный новый год. Слова благодарности и зависимости от Бога изначально не были современным концертным выступлением.\n\nТрудную историю нельзя скрывать\n\nНьютон участвовал в работорговле. Последующая религиозная жизнь не стёрла причинённого вреда, а его публичный вклад в движение за отмену рабства появился гораздо позже. В 1788 году он опубликовал «Thoughts upon the African Slave Trade». Содержательный рассказ о благодати не должен превращать эту историю в мгновенное и беспроблемное преображение.\n\nИзучите свидетельства\n\nМатериал музея объединяет гимн, исторический контекст и архивные документы. Прочитайте его, прежде чем считать доказанной любую популярную историю о происхождении песни. Отдельная музыкальная библиотека помогает найти исполнения, но не служит историческим источником.\n\nДля размышления\n\nЧем ощущение прощения отличается от принятия ответственности? Побудьте с этим вопросом, не торопясь к простому ответу. Это размышление Grace & Gather, не цитата Ньютона."},"resources":[["read","Cowper & Newton Museum","https://cowperandnewtonmuseum.org.uk/amazing-grace/"],["listen","Shane & Shane · song library","https://www.shaneandshane.com/learn-the-songs"]],"kind":"feed"}'::jsonb,true) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.content_items(id,kind,data,published) VALUES ('psalm-42','feed','{"id":"psalm-42","type":"psalms","icon":"wave","color":"lavender","source":"Scripture · Psalm 42 / 41","tags":["sadness","loneliness","hope"],"title":{"en":"Words for a heart that longs","pt":"Palavras para um coração com saudade","es":"Palabras para un corazón que anhela","ru":"Слова для тоскующего сердца"},"summary":{"en":"Psalm 42 lets sorrow and hope exist together. Its language of longing offers a way to bring difficult feelings into prayer without pretending that everything is already well.","pt":"O Salmo 42 deixa tristeza e esperança coexistirem. Sua linguagem de saudade ajuda a levar sentimentos difíceis à oração, sem fingir que tudo já está bem.","es":"El Salmo 42 permite que tristeza y esperanza convivan. Su lenguaje ayuda a llevar sentimientos difíciles a la oración sin fingir que todo está bien.","ru":"В Псалме 42 (41) печаль соседствует с надеждой. Его язык тоски помогает принести трудные чувства в молитву, не притворяясь, будто всё уже хорошо."},"body":{"en":"The USCCB’s study notes read Psalms 42–43 together as a lament of someone far from Jerusalem, longing for shared worship. This is an attributed interpretation, not a modern diagnosis of the speaker. Many Septuagint-based editions number this Psalm 41.","pt":"As notas da USCCB leem os Salmos 42–43 como o lamento de alguém longe de Jerusalém, com saudade do culto em comunidade. É uma interpretação atribuída, não um diagnóstico moderno. Em muitas edições da Septuaginta é o Salmo 41.","es":"La USCCB lee los Salmos 42–43 como el lamento de alguien lejos de Jerusalén que añora el culto comunitario. Es una interpretación, no un diagnóstico moderno. En muchas ediciones de la Septuaginta es el Salmo 41.","ru":"USCCB читает Псалмы 42–43 как плач человека вдали от Иерусалима, тоскующего по общему богослужению. Это толкование, а не современный диагноз. В изданиях на основе Септуагинты это Псалом 41."},"resources":[["study","USCCB · Catholic study notes","https://bible.usccb.org/bible/psalms/42"]],"kind":"feed"}'::jsonb,true) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.content_items(id,kind,data,published) VALUES ('simple-prayer','feed','{"id":"simple-prayer","type":"prayers","icon":"hands","color":"sage","source":"Grace & Gather · original reflection","tags":["sadness","peace","faith"],"title":{"en":"A prayer for the difficult days","pt":"Uma oração para os dias difíceis","es":"Una oración para los días difíciles","ru":"Молитва для тяжёлых дней"},"summary":{"en":"You do not need perfect words. Begin with what is true today: the sadness, the uncertainty, or the hope you can barely name. There is room for all of it in prayer.","pt":"Você não precisa de palavras perfeitas. Comece com a verdade de hoje: a tristeza, a incerteza ou a esperança que mal consegue nomear. Há espaço para tudo na oração.","es":"No necesitas palabras perfectas. Empieza con la verdad de hoy: tristeza, incertidumbre o una esperanza que apenas puedes nombrar. Hay espacio para todo en la oración.","ru":"Идеальные слова не нужны. Начните с правды сегодняшнего дня: печали, неуверенности или едва различимой надежды. В молитве есть место всему этому."},"body":{"en":"An original Grace & Gather prayer: “God, I am here as I am. Help me meet this day with gentleness. Show me one small way to care for myself and one person I can reach out to. Stay close as I take that step. Amen.” You can change these words or sit quietly.","pt":"Oração original do Grace & Gather: “Deus, estou aqui como sou. Ajude-me a viver este dia com gentileza. Mostre-me um pequeno cuidado comigo e alguém a quem posso procurar. Fique perto enquanto dou esse passo. Amém.” Adapte as palavras ou fique em silêncio.","es":"Oración original de Grace & Gather: “Dios, estoy aquí tal como soy. Ayúdame a vivir este día con ternura. Muéstrame un pequeño cuidado para mí y alguien a quien acudir. Acompáñame mientras doy ese paso. Amén.” Puedes cambiar las palabras o guardar silencio.","ru":"Молитва Grace & Gather: «Боже, я здесь такой, какой есть. Помоги прожить этот день бережно. Покажи маленький шаг заботы о себе и человека, к которому можно обратиться. Будь рядом, пока я делаю этот шаг. Аминь». Измените слова или побудьте в тишине."},"resources":[],"kind":"feed"}'::jsonb,true) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.content_items(id,kind,data,published) VALUES ('saint-joseph','feed','{"id":"saint-joseph","type":"prayers","tradition":"catholic","icon":"hands","color":"sand","source":"USCCB · Catholic","tags":["saints","family","protection"],"title":{"en":"Saint Joseph: prayer in difficulty","pt":"São José: oração na dificuldade","es":"San José: oración en la dificultad","ru":"Святой Иосиф: молитва в трудностях"},"summary":{"en":"A Catholic prayer asking Saint Joseph’s intercession for protection and help in adversity. Its history reaches back to Pope Leo XIII in 1889.","pt":"Uma oração católica pela intercessão de São José, pedindo proteção e auxílio na adversidade. Sua história remonta ao papa Leão XIII, em 1889.","es":"Una oración católica que pide la intercesión de San José para recibir protección y ayuda. Su historia se remonta al papa León XIII, en 1889.","ru":"Католическая молитва о заступничестве святого Иосифа, защите и помощи в беде. Её история восходит к папе Льву XIII и 1889 году."},"body":{"en":"The USCCB publishes the prayer composed by Leo XIII and recommended after the Rosary, especially during October. Open the official text for this devotional practice.","pt":"A USCCB publica a oração composta por Leão XIII e recomendada após o Rosário, especialmente em outubro. Abra o texto oficial para essa prática devocional.","es":"La USCCB publica la oración compuesta por León XIII y recomendada después del Rosario, especialmente en octubre. Abre el texto oficial de esta devoción.","ru":"USCCB публикует молитву Льва XIII, рекомендованную после Розария, особенно в октябре. Откройте официальный текст этой молитвы."},"resources":[["pray","USCCB · Saint Joseph","https://www.usccb.org/prayers/prayer-st-joseph-after-rosary"]],"kind":"feed"}'::jsonb,true) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.content_items(id,kind,data,published) VALUES ('saint-jude','feed','{"id":"saint-jude","type":"prayers","tradition":"catholic","icon":"hands","color":"lavender","source":"St. Jude Shrine · Pallottines","tags":["saints","fear","hope"],"title":{"en":"Saint Jude: companionship in suffering","pt":"São Judas: companhia no sofrimento","es":"San Judas: compañía en el sufrimiento","ru":"Святой Иуда: поддержка в страдании"},"summary":{"en":"The shrine’s Catholic prayer asks for comfort, courage, and companionship in times of suffering. Choose this prayer when you want words for a difficult moment.","pt":"A oração católica do santuário pede conforto, coragem e companhia no sofrimento. Encontre palavras para um momento difícil.","es":"La oración católica del santuario pide consuelo, valor y compañía en el sufrimiento. Encuentra palabras para un momento difícil.","ru":"Католическая молитва святилища просит утешения, смелости и поддержки в страдании. Найдите слова для трудного момента."},"body":{"en":"This devotional resource is published by the Pallottine St. Jude Shrine. Open the official page and select the prayer for times of suffering.","pt":"Este recurso devocional é publicado pelo santuário palotino de São Judas. Abra a página oficial e selecione a oração para momentos de sofrimento.","es":"Este recurso lo publica el santuario palotino de San Judas. Abre la página oficial y elige la oración para momentos de sufrimiento.","ru":"Материал опубликован паллотинским святилищем святого Иуды. На официальной странице выберите молитву во время страданий."},"resources":[["pray","St. Jude Shrine · prayers","https://stjudeshrine.org/prayers_to_st_jude/"]],"kind":"feed"}'::jsonb,true) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.content_items(id,kind,data,published) VALUES ('saint-juan-diego','feed','{"id":"saint-juan-diego","type":"prayers","tradition":"catholic","icon":"hands","color":"rose","source":"USCCB · Catholic","tags":["saints","loneliness","belonging"],"title":{"en":"Saint Juan Diego: belonging far from home","pt":"São Juan Diego: acolhimento longe de casa","es":"San Juan Diego: pertenecer lejos de casa","ru":"Святой Хуан Диего: близость вдали от дома"},"summary":{"en":"A Catholic prayer for migrants, separated families, and people who feel isolated. It also invites communities to offer a welcome.","pt":"Uma oração católica por migrantes, famílias separadas e pessoas que se sentem isoladas. Também convida as comunidades a acolher.","es":"Una oración católica por migrantes, familias separadas y personas aisladas. También invita a las comunidades a acoger.","ru":"Католическая молитва о мигрантах, разлучённых семьях и одиноких людях. Она также призывает общины к гостеприимству."},"body":{"en":"Published by the USCCB, this prayer asks Saint Juan Diego’s intercession and encourages hospitality toward people far from home.","pt":"Publicada pela USCCB, a oração pede a intercessão de São Juan Diego e incentiva a hospitalidade com quem está longe de casa.","es":"Publicada por la USCCB, pide la intercesión de San Juan Diego y anima a acoger a quienes están lejos de casa.","ru":"Молитва USCCB просит заступничества святого Хуана Диего и призывает принимать людей вдали от дома."},"resources":[["pray","USCCB · Saint Juan Diego","https://www.usccb.org/prayers/prayer-saint-juan-diego"]],"kind":"feed"}'::jsonb,true) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.content_items(id,kind,data,published) VALUES ('psalm-23-sung','feed','{"id":"psalm-23-sung","type":"music","icon":"music","color":"sage","source":"Shane & Shane · Psalms, Vol. 2","tags":["sadness","comfort","trust"],"title":{"en":"A psalm to accompany your walk","pt":"Um salmo para acompanhar a caminhada","es":"Un salmo para acompañar tu paseo","ru":"Псалом для вашей прогулки"},"summary":{"en":"“Psalm 23 (Surely Goodness, Surely Mercy)” is a contemporary song inspired by the shepherd psalm. Let it accompany a quiet moment or a gentle walk, if music feels welcome today.","pt":"“Psalm 23 (Surely Goodness, Surely Mercy)” é uma canção contemporânea inspirada no salmo do pastor. Pode acompanhar um momento tranquilo ou uma caminhada, se a música for bem-vinda hoje.","es":"“Psalm 23 (Surely Goodness, Surely Mercy)” es una canción inspirada en el salmo del pastor. Puede acompañar un momento tranquilo o un paseo, si hoy te apetece escuchar música.","ru":"«Psalm 23 (Surely Goodness, Surely Mercy)» — современная песня по мотивам псалма о пастыре. Она может сопровождать тихий момент или прогулку, если сегодня хочется музыки."},"body":{"en":"Released on Psalms, Vol. 2 in 2015, this setting draws on Psalm 23’s language of guidance and care. It is a song adaptation, not an exact Bible translation. Listen on the artist’s official channel; you can also read the psalm in your selected edition below.","pt":"Lançada em Psalms, Vol. 2 em 2015, a canção retoma o cuidado e a orientação do Salmo 23. É uma adaptação musical, não uma tradução bíblica exata. Ouça no canal oficial e leia o salmo na edição selecionada abaixo.","es":"Publicada en Psalms, Vol. 2 en 2015, retoma el cuidado y la guía del Salmo 23. Es una adaptación musical, no una traducción bíblica exacta. Escucha en el canal oficial y lee el salmo en tu edición abajo.","ru":"Песня вышла на Psalms, Vol. 2 в 2015 году и обращается к образам заботы и водительства. Это музыкальное переложение, а не точный перевод. Послушайте на официальном канале и прочтите псалом в выбранном издании ниже."},"resources":[["listen","Shane & Shane · Psalm 23","https://www.youtube.com/watch?v=OoojA0cLPWY"]],"kind":"feed"}'::jsonb,true) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.content_items(id,kind,data,published) VALUES ('bible-class','course','{"id":"bible-class","category":"theology","icon":"book","color":"sage","provider":"BibleProject Classroom","format":"course","lang":"English","title":{"en":"Learn to read the Bible in context","pt":"Aprenda a ler a Bíblia em contexto","es":"Aprende a leer la Biblia en contexto","ru":"Читайте Библию в контексте"},"summary":{"en":"Free classes exploring biblical language, literature, and history. Begin with Introduction to the Hebrew Bible.","pt":"Aulas gratuitas sobre linguagem, literatura e história bíblicas. Comece com a introdução à Bíblia Hebraica.","es":"Clases gratuitas sobre lenguaje, literatura e historia bíblicos. Empieza con la introducción a la Biblia hebrea.","ru":"Бесплатные занятия о языке, литературе и истории Библии. Начните с введения в Еврейскую Библию."},"url":"https://bibleproject.com/classroom/","kind":"course"}'::jsonb,true) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.content_items(id,kind,data,published) VALUES ('mindful','course','{"id":"mindful","category":"mindfulness","icon":"leaf","color":"lavender","provider":"UCLA Mindful","format":"guided","lang":"Multiple languages","title":{"en":"A gentle introduction to mindfulness","pt":"Uma introdução gentil à atenção plena","es":"Una introducción amable al mindfulness","ru":"Мягкое знакомство с осознанностью"},"summary":{"en":"Start with free guided meditations from UCLA. Choose a language and a practice that feels comfortable.","pt":"Comece com meditações guiadas gratuitas da UCLA. Escolha um idioma e uma prática confortável.","es":"Empieza con meditaciones guiadas gratuitas de UCLA. Elige un idioma y una práctica cómoda.","ru":"Начните с бесплатных медитаций UCLA. Выберите язык и комфортную практику."},"url":"https://www.uclahealth.org/uclamindful/free-guided-meditations","kind":"course"}'::jsonb,true) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.content_items(id,kind,data,published) VALUES ('breath-start','course','{"id":"breath-start","category":"breathwork","icon":"breath","color":"sand","provider":"Grace & Gather","format":"miniCourse","lang":"en · pt · es · ru","title":{"en":"Breathing, without pressure","pt":"Respirar, sem pressão","es":"Respirar, sin presión","ru":"Дыхание без напряжения"},"summary":{"en":"Three short lessons: settle comfortably, notice a natural breath, and try a quiet minute.","pt":"Três lições: acomodar-se, perceber a respiração natural e experimentar um minuto tranquilo.","es":"Tres lecciones: acomodarte, notar la respiración natural y probar un minuto tranquilo.","ru":"Три коротких урока: устроиться удобно, заметить естественное дыхание и попробовать минуту тишины."},"lessons":["breath1","breath2","breath3"],"url":"https://www.nhsinform.scot/healthy-living/mental-wellbeing/breathing-and-relaxation-exercises/","kind":"course"}'::jsonb,true) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.content_items(id,kind,data,published) VALUES ('journal-start','course','{"id":"journal-start","category":"journaling","icon":"pen","color":"rose","provider":"Grace & Gather","format":"miniCourse","lang":"en · pt · es · ru","title":{"en":"Your first honest page","pt":"Sua primeira página sincera","es":"Tu primera página sincera","ru":"Первая искренняя страница"},"summary":{"en":"A simple introduction to noticing, writing without judgment, and choosing one small next step.","pt":"Uma introdução a perceber, escrever sem julgamento e escolher um pequeno próximo passo.","es":"Una introducción a observar, escribir sin juzgar y elegir un pequeño siguiente paso.","ru":"Введение в наблюдение, письмо без осуждения и выбор небольшого следующего шага."},"lessons":["journal1","journal2","journal3"],"kind":"course"}'::jsonb,true) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.content_items(id,kind,data,published) VALUES ('music-theory','course','{"id":"music-theory","category":"music","icon":"music","color":"sand","provider":"The Open University · OpenLearn","format":"course","lang":"English","title":{"en":"An introduction to music theory","pt":"Uma introdução à teoria musical","es":"Introducción a la teoría musical","ru":"Введение в теорию музыки"},"summary":{"en":"Explore notation, rhythm, pitch, and the building blocks of music in this free introductory course.","pt":"Explore notação, ritmo, altura e fundamentos da música neste curso introdutório gratuito.","es":"Explora notación, ritmo, altura y fundamentos musicales en este curso gratuito.","ru":"Изучите нотную запись, ритм, высоту звука и основы музыки на бесплатном вводном курсе."},"url":"https://www.open.edu/openlearn/history-the-arts/music/an-introduction-music-theory/content-section-0","kind":"course"}'::jsonb,true) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.content_items(id,kind,data,published) VALUES ('art-pause','course','{"id":"art-pause","category":"art","icon":"art","color":"lavender","provider":"Grace & Gather","format":"miniCourse","lang":"en · pt · es · ru","title":{"en":"Make space on the page","pt":"Abra espaço no papel","es":"Haz espacio en el papel","ru":"Дайте место творчеству"},"summary":{"en":"A free creative practice: observe one object, sketch its outline, and notice what the process brings up.","pt":"Uma prática criativa gratuita: observar um objeto, desenhar seu contorno e perceber o que surge.","es":"Una práctica creativa gratuita: observar un objeto, dibujar su contorno y notar lo que surge.","ru":"Бесплатная творческая практика: наблюдайте предмет, рисуйте его контур и замечайте свои ощущения."},"lessons":["art1","art2","art3"],"kind":"course"}'::jsonb,true) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
